package com.hookdeveloper.catlive.remote;
import android.view.*;import android.widget.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.Config;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31,qualifiers="w393dp-h851dp-port")
public class RemoteDialogLayoutTest {
 ActivityController<MainActivity> controller;MainActivity app;
 @Before public void start()throws Exception{controller=Robolectric.buildActivity(MainActivity.class).setup();app=controller.get();app.entering=true;app.remote.connected=true;app.remote.mode="director";app.remote.state=new JSONObject(new String(getClass().getResourceAsStream("/remote-state.json").readAllBytes(),StandardCharsets.UTF_8));app.onChanged();}
 @After public void close(){app.closeDialog();controller.pause().stop().destroy();}
 LinearLayout measure(int maxHeight){FrameLayout content=app.activeDialog.findViewById(android.R.id.content);LinearLayout box=(LinearLayout)content.getChildAt(0);box.measure(View.MeasureSpec.makeMeasureSpec(RemoteWidgets.dp(369),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(RemoteWidgets.dp(maxHeight),View.MeasureSpec.AT_MOST));box.layout(0,0,box.getMeasuredWidth(),box.getMeasuredHeight());return box;}
 @Test public void shortConfirmationFitsContentInsteadOfGrowingTo520Points(){app.confirm("Sair do Remote?","A reprodução continua no computador.","Sair",()->fail("Must not confirm automatically"));LinearLayout box=measure(800);assertEquals(ViewGroup.LayoutParams.WRAP_CONTENT,app.activeDialog.getWindow().getAttributes().height);assertTrue(box.getHeight()>RemoteWidgets.dp(100));assertTrue("No large blank area",box.getHeight()<RemoteWidgets.dp(240));View buttons=box.getChildAt(2);assertEquals(RemoteWidgets.dp(40),buttons.getHeight());assertTrue(buttons.getBottom()<=box.getHeight());}
 @Test public void longContentScrollsAndActionsRemainVisibleWithKeyboard(){LinearLayout rows=RemoteWidgets.column(app);for(int i=0;i<30;i++)rows.addView(RemoteWidgets.label(app,"Projeto "+i,16,RemoteWidgets.TEXT),new LinearLayout.LayoutParams(-1,RemoteWidgets.dp(40)));app.dialog("Projetos recentes",rows,"Fechar",()->{});LinearLayout box=measure(800);assertEquals(RemoteWidgets.dp(520),box.getHeight());ScrollView scroll=(ScrollView)box.getChildAt(1);assertTrue(rows.getMeasuredHeight()>scroll.getHeight());box=measure(240);assertTrue(box.getHeight()<=RemoteWidgets.dp(240));assertEquals(RemoteWidgets.dp(40),box.getChildAt(2).getHeight());assertTrue(box.getChildAt(2).getBottom()<=box.getHeight());}
 @Test public void playlistInputKeepsOnlyOneTextField(){app.input("Nome da playlist","Repertório",false,name->{});LinearLayout box=measure(800);ScrollView scroll=(ScrollView)box.getChildAt(1);assertEquals(1,scroll.getChildCount());assertTrue(scroll.getChildAt(0) instanceof EditText);assertEquals("Repertório",((EditText)scroll.getChildAt(0)).getText().toString());assertTrue(box.getHeight()<RemoteWidgets.dp(240));}
 @Test public void remoteSongsOnlyExposeDrawerAndNormalRowsNeverOpenEmptyPopup()throws Exception{
  JSONObject parent=new JSONObject().put("id","P").put("name","Música"),child=new JSONObject().put("id","C").put("parentRegion","P").put("start",10),ordinary=new JSONObject().put("id","N");app.state.put("timelineRegions",new JSONArray().put(parent).put(child).put(ordinary));
  for(String playlist:new String[]{"SET",""}){app.state.put("selectedPlaylist",playlist);app.expanded.clear();assertEquals(Collections.singletonList("Abrir gaveta"),app.regionMenuChoices(parent));app.expanded.add("P");assertEquals(Collections.singletonList("Fechar gaveta"),app.regionMenuChoices(parent));assertTrue(app.regionMenuChoices(child).isEmpty());assertTrue(app.regionMenuChoices(ordinary).isEmpty());app.regionMenu(new View(app),ordinary);assertNull(app.activeDialog);}
 }
 @Test public void completeStartupArtworkFitsInsideSystemSplashMask(){android.graphics.drawable.LayerDrawable startup=(android.graphics.drawable.LayerDrawable)app.getDrawable(R.drawable.catlive_startup);int size=RemoteWidgets.dp(288);startup.setBounds(0,0,size,size);android.graphics.Rect art=startup.getDrawable(1).getBounds();double radius=RemoteWidgets.dp(192)/2.0,cx=size/2.0,cy=size/2.0;for(int x:new int[]{art.left,art.right})for(int y:new int[]{art.top,art.bottom})assertTrue("Logo corner outside Android splash mask",Math.hypot(x-cx,y-cy)<=radius);assertEquals(art.width(),art.height());}
 void verifyWelcomeLogo(){app.showWelcome();ImageView logo=app.root.findViewWithTag("welcome-logo");assertEquals(ImageView.ScaleType.FIT_CENTER,logo.getScaleType());int width=app.getResources().getDisplayMetrics().widthPixels,height=app.getResources().getDisplayMetrics().heightPixels;app.root.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));app.root.layout(0,0,width,height);android.graphics.RectF mapped=new android.graphics.RectF(0,0,logo.getDrawable().getIntrinsicWidth(),logo.getDrawable().getIntrinsicHeight());logo.getImageMatrix().mapRect(mapped);assertTrue(mapped.left>=-.01&&mapped.top>=-.01);assertTrue(mapped.right<=logo.getWidth()+.01&&mapped.bottom<=logo.getHeight()+.01);}
 @Test public void welcomeLogoFitsPhone(){verifyWelcomeLogo();}
 @Test @Config(qualifiers="sw800dp-w1280dp-h800dp-land") public void welcomeLogoFitsTablet(){verifyWelcomeLogo();}
}
